#include <memory>
#include <iostream>

struct Vec3 {
    int x, y, z;
    Vec3(int x = 0, int y = 0, int z = 0) noexcept : x(x), y(y), z(z) {}
};

int main() {
    // Non-array types
    auto v1 = std::make_unique<Vec3>();           // default constructor
    auto v2 = std::make_unique<Vec3>(0, 1, 2);     // with arguments

    // Array type (unknown bound)
    auto arr = std::make_unique<Vec3[]>(5);        // 5 value-initialized elements

    std::cout << "v2: {" << v2->x << ", " << v2->y << ", " << v2->z << "}\n";
    return 0;
}

